 $html .= '<script>(function(){const root=document.getElementById("odpc-tv");if(!root)return;const channels=JSON.parse(root.dataset.channels||"[]"),v=root.querySelector("video"),status=root.querySelector("#odpc-tv-status"),grid=root.querySelector("#odpc-tv-grid"),search=root.querySelector("#odpc-tv-search"),only=root.querySelector("#odpc-tv-favs-only");let h=null;let fav=[];try{fav=JSON.parse(localStorage.getItem("odpc-tv-favorites-v1")||"[]")}catch(e){}function play(c){if(h){h.destroy();h=null}v.pause();v.removeAttribute("src");v.load();status.textContent="Verbinde: "+c.name;if(window.Hls&&Hls.isSupported()){h=new Hls({enableWorker:true});h.loadSource(c.url);h.attachMedia(v);h.on(Hls.Events.MANIFEST_PARSED,()=>v.play().catch(()=>status.textContent="Zum Starten Play drücken"));h.on(Hls.Events.ERROR,(_,e)=>{if(e.fatal){status.textContent="Dieser Stream ist derzeit nicht abspielbar ("+e.type+"). Bitte anderen Sender wählen.";h.destroy();h=null}})}else if(v.canPlayType("application/vnd.apple.mpegurl")){v.src=c.url;v.play().catch(()=>status.textContent="Zum Starten Play drücken")}else status.textContent="HLS wird in diesem Browser nicht unterstützt"}function render(){grid.replaceChildren();const q=search.value.trim().toLowerCase();for(const c of channels){if(!c.name.toLowerCase().includes(q)||(only.checked&&!fav.includes(c.name)))continue;const wrap=document.createElement("div");wrap.style.cssText="display:flex;gap:3px";const b=document.createElement("button");b.type="button";b.textContent=c.name+(c.available?" · "+c.quality:" · nicht verfügbar");b.disabled=!c.available;b.style.cssText="flex:1;min-width:0;overflow-wrap:anywhere;background:#254d80;color:#fff;border:0;border-radius:8px;padding:12px;cursor:pointer";if(!c.available){b.style.opacity=".48";b.title="Kein bestätigter frei einbettbarer HD-Stream vorhanden"}else b.onclick=()=>play(c);const star=document.createElement("button");star.type="button";star.textContent=fav.includes(c.name)?"★":"☆";star.setAttribute("ari